import pathlib,json,datetime,hashlib
R=pathlib.Path.cwd();D='2026-11-01';NOW=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()
def load(p):return json.loads((R/p).read_text(encoding='utf-8-sig'))
def save(p,v):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
r=load(f'docs/daily-reports/{D}.json');over=load('src/data/i18n/en-overrides.json');photos={p['key']:p for p in load(f'docs/image-licenses/{D}.json')}
def t(a,b):
 over[a]=b
 if a.startswith('#'):over[a.lstrip('# ')]=b.lstrip('# ')
 return a
def photo(k):
 p=photos[k];return dict(image='/'+p['file'].removeprefix('public/'),imageAlt=t('授權建築資料照，非新聞活動現場','Licensed archive building photograph, not the reported event'),imageCredit=p['author']+' / '+p['license'],imageSource=p['source'],imageLicense=p['license'])
def md(path,fm,pairs,k):
 p=R/path;assert not p.exists(),path
 p.write_text('---\n'+''.join(k+': '+json.dumps(v,ensure_ascii=False)+'\n' for k,v in fm.items())+'---\n\n'+'\n\n'.join(t(a,b) for a,b in pairs)+f'\n\n[Photo credits](/images/daily/{D}/credits.html#{k})\n',encoding='utf8')
 for suf,en in [('｜環球教育新聞網 Global Education News',' | Global Education News'),('｜台灣國際獎學金雷達',' | Taiwan Global Scholarship Radar')]:over[fm['title']+suf]=over[fm['title']]+en
