def article(k,slug,zh,en,desc,de,pairs):
 path='src/pages/news/'+slug+'.md';sources=[dict(label='Source '+str(i+1),url=u) for i,u in enumerate(U[k])]
 md(path,dict(layout='../../layouts/ArticleLayout.astro',title=t(zh,en),description=t(desc,de),date=NOW,author='LTU Global Education News 編輯部',category=t('國際教育新聞','International education news'),topic={'us':'usa','au':'australia','th':'asia'}[k],tags=[k,'2026'],sources=sources,**photo(k)),pairs,k)
 news.append(dict(slug=slug,title=zh,url='https://globalednews.com/news/'+slug+'/',publishedPath=path,sources=sources,verifiedAt=NOW))
article('us','us-accreditation-aim-final-rule-october-2026','美國公布高教認證最終規則：2027年7月生效','US publishes final accreditation rule effective July 2027','選校須核對現行認證，不能把改革當成學位自動失效。','Check current accreditation; reform does not automatically invalidate degrees.',[
('## 公告與生效分開看','## Publication and commencement are different'),('美國教育部10月30日公布AIM高教認證最終規則，涵蓋認證機構認可、學校資格與學生援助規定，整體生效日為2027年7月1日。部分條文可自2027年1月提早實施，但認證機構不得因此提前對學校施加7月前生效的新要求。','The October 30 AIM final rule revises accreditor recognition, institutional eligibility and student assistance regulations. Its general effective date is July 1, 2027. Optional early implementation begins in January, but agencies cannot thereby impose new institutional requirements taking effect before July.'),
('## 認證程序將調整','## Accreditation procedures will change'),('Inside Higher Ed指出，規則加快新認證機構取得聯邦認可的程序，便利學校更換認證機構，並涉及學分轉移、研究誠信等標準。MSCHE亦確認生效日期，表示將持續檢視規則並提供指引。這是制度變更，不是任何特定學校已失去資格的公告。','Inside Higher Ed reports faster federal recognition for new accreditors, easier changes of accreditor and standards involving credit transfer and research integrity. MSCHE confirms the effective date and plans further guidance. This is a regulatory change, not a notice that any particular school has lost status.'),
('## 台灣家庭如何選校','## What Taiwan applicants can check'),('編輯建議：保留學校與科系當前認證查詢紀錄，另查專業證照與台灣學歷採認要求；遇到學校更換認證機構，向校方索取正式時程與學生保障說明。不可把聯邦認可、錄取或簽證視為同一件事。配圖為美國教育部大樓資料照。','Editorial guidance: retain current institutional and program accreditation records and separately check professional licensing and Taiwan recognition requirements. If an accreditor changes, request a formal timeline and student safeguards. Accreditation, admission and immigration approval are separate matters. The photograph shows the Education Department building.')])
article('th','qmul-kmutt-thailand-dual-engineering-2027','英泰合作三項工程雙學位：2027年在曼谷授課','Queen Mary and KMUTT plan three engineering dual degrees in Bangkok','四年課程涵蓋資料AI、智慧電機電子與機器人；台灣申請資格須另核對。','Four-year programs cover data and AI, intelligent electronics and robotics; Taiwan eligibility needs separate confirmation.',[
('## 合作已啟動，課程自2027年展開','## Partnership launched; programs start in 2027'),('Queen Mary於10月28日宣布與泰國KMUTT合作，自2027年共同開設三項四年制工程學士課程：資料與人工智慧、智慧電子與電機系統、機器人與人工智慧。英方教師將與泰方教師在曼谷共同授課。','Queen Mary announced the partnership on October 28. Three four-year engineering degrees begin in 2027: Data and Artificial Intelligence Engineering, Intelligent Electronic and Electrical System Engineering, and Robotics and Artificial Intelligence Engineering. Academics from both universities will teach in Bangkok.'),
('## 招生頁提供第二項直接證據','## A separate admissions record corroborates the route'),('KMUTT自己的2027招生頁列出此雙學位方案，當輪期間為10月27日至12月28日，並說明可在泰國完成兩校學位。這是泰方招生紀錄，並非轉載英方新聞稿；但頁面屬TCAS招生架構，不能直接推論台灣高中生都適用。','KMUTT independently lists the dual degree in its 2027 admissions calendar, with an October 27–December 28 round and study in Thailand leading to both degrees. This operational admissions record is separate from the UK release. Its TCAS context does not establish eligibility for every Taiwan school leaver.'),
('## 申請前先問清楚的事項','## Questions to settle before applying'),('台灣學生應確認國際申請入口、學歷等值、英文門檻、四年總費用及學位授予條件。海外合作課程不等於必須赴英，也不自動帶來英國畢業工作資格。本文以英方倫敦校舍資料照作為機構辨識，並非曼谷新課程現場。','Taiwan applicants should confirm the international route, credential equivalency, English requirements, full costs and award conditions. A partnership does not imply UK attendance or UK post-study work eligibility. The archive photograph identifies Queen Mary’s London campus; it does not show the Bangkok program.')])
article('au','ieaa-excellence-awards-student-learning-2026','澳洲IEAA公布教育獎項：教學與海外學習成效成焦點','IEAA awards highlight teaching and learning-abroad evidence','獎項可作為課程研究線索，不能當成個人學習成果保證。','Awards offer leads for course research, not guarantees of individual outcomes.',[
('## 10月27日公布得獎名單','## Winners announced on October 27'),('IEAA在雪梨第40屆AIEC開幕全體會議公布2026卓越獎。南十字星大學Academic Portfolio Office的Southern Cross Model獲最佳實務獎；miXabroad的海外學習全球比較基準計畫獲創新獎。','IEAA announced its 2026 Excellence Awards at the opening plenary of the 40th AIEC in Sydney. Southern Cross University’s Academic Portfolio Office won Best Practice for the Southern Cross Model; miXabroad’s global learning-abroad benchmark won Innovation.'),
('## 從獎項讀到什麼','## What the awards help applicants investigate'),('The PIE另報導，miXabroad將學生聲音與跨計畫、群體及國家的比較證據連結。得獎說明教育品質不只在排名，也涉及如何衡量學生經驗；但這是獎項報導，並非本刊自行完成的因果成效研究。','The PIE reports that miXabroad links student voices with comparative evidence across programs, cohorts and countries. The award invites scrutiny of how providers measure experience beyond rankings. This is an awards report, not an independent causal evaluation by this publication.'),
('## 台灣學生的課程比較清單','## A course comparison checklist'),('編輯建議：詢問每學期修課負擔、評量方式、學習支援、交換學分採計及學生意見處理程序，再比較學費與生活費。不把得獎直接解讀成保證畢業或就業。照片為澳洲National Marine Science Centre歷史建築資料照，非頒獎會場。','Editorial guidance: compare workload, assessment, academic support, credit recognition and feedback processes alongside total costs. An award guarantees neither graduation nor employment. The image is an archive photograph of Australia’s National Marine Science Centre, not the ceremony.')])
def award(k,slug,zh,en,fund,fe,deadline,de,note,ne,pairs):
 path='src/pages/scholarships/items/'+slug+'.md';sources=[dict(label='Source '+str(i+1),url=u) for i,u in enumerate(U[k])]
 assert slug not in r['scholarshipBaselineSlugs']
 md(path,dict(layout='../../../layouts/ScholarshipLayout.astro',title=t(zh,en),description=t(note,ne),date=D,author='LTU Global Education News 編輯部',country='美國',level='學士',funding=t(fund,fe),deadline=t(deadline,de),status='開放中',sourceName='Official provider / independent cross-check',officialUrl=U[k][0],secondSourceUrl=U[k][1],eligibilityTW='可申請',taiwanNote=t(note,ne),verificationDate=D,featuredDate=D,featuredUntil='2026-11-02T00:00:00+08:00',category='大學國際生獎學金',sources=sources,**photo(k)),pairs,k)
 awards.append(dict(slug=slug,title=zh,url='https://globalednews.com/scholarships/items/'+slug+'/',publishedPath=path,isNew=True,baselineAbsent=True,eligibleTaiwan=True,open=True,verifiedAt=NOW,sources=sources,updateSummary='New award absent from 236-slug baseline; official terms and second source read.'))
award('wichita','2026-11-wichita-global-select','Wichita Global Select：國際學士生學費減免36%','Wichita Global Select: 36% undergraduate tuition discount','學士學費減免36%，不含雜費','36% undergraduate tuition discount, excluding fees','2027春季Premium 12月1日；秋季Basic 4月15日','Spring 2027 Premium December 1; Fall Basic April 15','台灣非移民身分學位新生可評估；學士GPA須達3.0等值。','Taiwan degree entrants with eligible nonimmigrant status may qualify with a 3.0-equivalent GPA.',[
('## 自動評估與實際金額','## Automatic assessment and the award'),('Global Select在錄取時評估，學士申請者須達美制GPA3.0或等值；入學表中回答獎學金問題。官方與Borderless均確認學士學費減免36%，依修讀學分計算，不含雜費；估算金額不能取代個別帳單。','Global Select is assessed at admission using a US-equivalent 3.0 GPA for undergraduates and a scholarship question on the admission form. Official terms and Borderless confirm a 36% tuition discount calculated by credits, excluding fees. Estimates do not replace an individual bill.'),
('## 開放路徑與台灣資格','## Open routes and Taiwan eligibility'),('官方國際生定義不排除台灣，須非美國公民、永久居民、難民或庇護身分。2027春季一般服務11月1日截止、Premium至12月1日；秋季Basic至4月15日。較快處理不是錄取或簽證保證，研究所不能套用加速服務。','The international category includes eligible Taiwan applicants and excludes US citizens, permanent residents, refugees and asylees. Spring 2027 Standard closes November 1 and Premium December 1; Fall Basic closes April 15. Expedited processing guarantees neither admission nor a visa and does not apply to graduate applications.'),
('## 排除條件','## Exclusions'),('已領居民或其他折扣學費、線上與固定收費課程可能不適用；入學後才達成績門檻通常不重新評估。請先核對完整費用與入學條件。本文只計一項Global Select，不把學士與研究所級距拆成兩項。','Resident or other discounted tuition, online study and fixed-fee programs may be excluded. Later improvement in grades normally does not trigger reassessment. Check full costs and admissions requirements. Global Select counts as one award, without splitting its degree-level rates.')])
award('cwu','2026-11-central-washington-international','Central Washington國際生獎助：按入學成績評估','Central Washington international merit awards assessed at admission','官網列USD6,979／9,294／12,380級距','Published tiers: USD6,979 / 9,294 / 12,380','2027春季入學優先日2月1日','Spring 2027 admission priority February 1','台灣國際學位生可申請；交換、政府資助、語言班與居民學費者排除。','Taiwan international degree students may qualify; exchange, government-sponsored, language and resident-rate students are excluded.',[
('## 成績決定級距','## Grades determine the tier'),('官方列入學成績2.7至2.9對應6,979美元、3.0至3.6對應9,294美元、3.7至4.0對應12,380美元；Borderless亦列相同級距。以錄取後正式獎助通知為準，不把最高金額當成人人可領。','Official tiers are USD6,979 for grades 2.7–2.9, USD9,294 for 3.0–3.6 and USD12,380 for 3.7–4.0, also listed by Borderless. The formal award letter controls; the maximum is not universal.'),
('## 現在可申請哪一季','## The current admission route'),('官網列2027春季入學優先日為2月1日，全年收件並在優先日後視名額受理。獎助隨錄取自動評估，合格者仍須完成確認表。台灣學歷與英語條件依國際入學程序審查，這不是免審錄取。','The official Spring 2027 priority date is February 1; applications continue subject to space. Awards are assessed automatically at admission but eligible recipients must confirm them. Taiwan credentials and English evidence undergo international admission review.'),
('## 續領與限制','## Renewal and exclusions'),('每年依春季累積成績重新評估；交換、政府資助、語言班與居民學費者不適用。官網留有部分舊季文字，本篇只採明列2027春季的日期，不沿用舊秋季日期。','Awards are reassessed using spring cumulative grades. Exchange, government-sponsored, language and resident-rate students are excluded. Some old term labels remain on the page; this entry uses its explicit Spring 2027 date, not the stale fall row.')])
award('wsu','2026-11-wsu-international-merit-spring-2027','WSU在校國際生Merit Award：春季1月1日截止','WSU International Merit Award: spring deadline January 1','每學期USD2,000學費減免，最多四學期','USD2,000 tuition waiver per semester, up to four semesters','春季1月1日；每學期須重新申請','Spring January 1; reapply each semester','適用在Pullman就讀、持F-1的台灣學士學位生；非高中直入新生獎。','For Taiwan F-1 undergraduates already studying at Pullman; not a school-leaver entrance award.',[
('## 先確認是在校生獎','## A continuing-student award'),('此獎限Pullman校區F-1學士學位生。可憑WSU累積GPA3.60且至少12學分，或近兩年特殊服務、突出成就申請；後兩項須提供說明與推薦。台灣學生符合相同在校與身分條件即可申請。','This award serves F-1 degree undergraduates at Pullman. Routes include a 3.60 WSU GPA with at least 12 credits, unusual service or extraordinary achievement in the past two years. The latter routes require a statement and recommendation. Taiwan students must meet the same status and enrollment conditions.'),
('## 金額、表單與期限','## Amount, form and deadline'),('官方提供申請入口，春季1月1日截止，每學期2,000美元、最多四學期，且每學期重新申請。第二來源Award Scholar的摘要標8月1日，但展開說明亦區分秋春期限；本篇採官方春季日期，不把每年4,000美元寫成一次發放。','The official page links an application, with a January 1 spring deadline, USD2,000 per semester and a four-semester maximum. Reapplication is required each term. Award Scholar highlights August 1, but its expanded description distinguishes fall and spring. This entry follows the official spring date rather than treating USD4,000 annually as a lump sum.'),
('## 不能直接當入學資金','## Do not assume funding before eligibility'),('自2026秋季起官方允許與International Academic Award合併，但這不是新生自動取得本獎的保證。申請者應預留未獲獎時的全額預算，並向國際處確認個別學籍資格。','Official terms allow combination with the International Academic Award from Fall 2026. This does not guarantee the Merit Award to new entrants. Budget for the full cost until funding is confirmed and check individual eligibility with International Programs.')])
slug='wichita-global-select-tuition-budget-2027';title=t('Wichita留學DIY：36%減免後仍要算哪些費用？','Wichita study guide: what remains after a 36% tuition discount?');path='src/pages/study-abroad/'+slug+'.md'
md(path,dict(layout='../../layouts/ArticleLayout.astro',title=title,description=t('分開學費折扣、雜費與生活預算，選對2027入學處理時程。','Separate tuition discounts, fees and living costs when planning 2027 entry.'),date=NOW,author='LTU Global Education News 編輯部',category='留學DIY導航',topic='usa',tags=['Wichita','2027'],sources=[dict(label='Official',url=u) for u in U['wichita'][::2]],**photo('diy')),[
('## 先認識校園，再認識帳單','## Explore the campus, then the bill'),('配圖是Wichita State校園內第一間Pizza Hut建築的歷史資料照，不是留學成功案例。選校可以從校園故事開始，付款前仍要回到課程、學分與正式費用。','The archive image shows the original Pizza Hut building at Wichita State, not a study-abroad success story. Campus history can spark interest; decisions still require course, credit and fee information.'),
('## 折扣只套用學費','## Apply the discount only to tuition'),('Global Select學士36%折扣不含雜費。預算表應將學費、必要費用、住宿、餐食、保險、交通分開，只有獲確認的學費項目扣減；不要把總生活成本乘以64%。完整條件見[獎學金雷達](/scholarships/)。','The undergraduate 36% discount excludes fees. Separate tuition, required fees, housing, meals, insurance and transport; reduce only confirmed eligible tuition, rather than multiplying the whole budget by 64%. Read the [scholarship radar](/scholarships/).'),
('## 處理快不代表簽證快','## Faster processing is not faster immigration approval'),('2027春季Premium入學服務12月1日截止，秋季Basic為4月15日；服務費、審查完整文件與簽證是不同環節。用[留學DIY導航](/study-abroad/)比較其他學校時，也保留替代入學季與全額預算。','Spring 2027 Premium closes December 1 and Fall Basic April 15. Processing fees, complete-document review and visas are separate steps. When comparing options through the [study abroad guide](/study-abroad/), retain an alternative start term and a full-cost budget.')],'diy')
